// Standard questions, ccarp. Original items written against the published exam guide. Built from content/en by tools/build-en.js.
window.QUESTIONS = window.QUESTIONS || {};
window.QUESTIONS.ccarp = [
// ---- Domain 1: Solution design and architecture (17%) ----
{ id:'ccarp-1-01', d:1, o:0, q:"An insurer says it wants to halve the time claims processing takes. What should the architect do first?",
  c:["Break down the business flow, and find the bottlenecks and the steps that suit an LLM before designing anything", "Propose replacing every step with an autonomous agent, keeping people out of it to cut the time in one move", "Bring in the top model and leave the flow as it is, letting the staff at each step use it through a chat window", "Build a general chatbot for the whole company, and decide where it fits the flow after seeing how it is used"],
  a:[0], e:"The first step in turning a business problem into an AI solution is to break the problem down and find where AI applies. Do not start from the means." },
{ id:'ccarp-1-02', d:1, o:0, q:"A department says it simply wants to use AI. Choose the two criteria that fit for picking a use case with real value.",
  c:["The impact of an error is manageable, and a person can verify it", "It is frequent, document-centered, and its current cost is measurable", "It is technically new and likely to draw attention inside and outside", "Executives are interested in it, so a budget is easy to obtain"],
  a:[0,1], e:"Start from work where risk is manageable, frequency is high and results can be measured. Buzz is not a measure of value." },
{ id:'ccarp-1-03', d:1, o:1, q:"In an end-to-end design of input → processing → output → feedback loop, what is the role of the feedback loop?",
  c:["Collect output quality, user corrections and rejections, and return them to improve prompts and evaluation data", "Generate the output twice for the same input, adopt it if both match, and generate a third time if they do not", "Validate the input data, and when the format is wrong or values are missing, reject it before processing", "Delete the logs once processing ends, so no personal or confidential data remains and storage stays small"],
  a:[0], e:"A feedback loop returns the signals gained in operation to improvement. Build it in at the design stage." },
{ id:'ccarp-1-04', d:1, o:1, q:"In a contract review system, which element must always be placed at the output stage?",
  c:["Criteria for routing to human review, and the basis of the output (quotes of the relevant clauses)", "Automatic sending of the output to the contract management system, removing manual work by staff", "Encryption of the stored output, so that only staff with the right permission can decrypt it", "A three-line summary of the output, so that the person in charge can read it in a short time"],
  a:[0], e:"For output in a high-risk domain, human-in-the-loop and showing the basis are design requirements." },
{ id:'ccarp-1-05', d:1, o:2, q:"Which is the correct account of choosing between an augmented LLM, a workflow and an agent?",
  c:["Augmented LLM to add tools, a workflow when the steps are fixed, an agent when they are decided dynamically", "An agent is always best for any requirement; the more the model decides, the higher the quality and flexibility", "A workflow is always best for any requirement; the more code controls, the more predictable and safe it gets", "The three differ only in what the implementation is called, and the result is the same whichever you choose"],
  a:[0], e:"Keep complexity to the minimum needed. A workflow has the edge in predictability, cost and testability." },
{ id:'ccarp-1-06', d:1, o:2, q:"Monthly report generation (fetch data → aggregate → write up → distribute) follows the same steps every time. Which pattern is recommended?",
  c:["A workflow controlled by code (calling the LLM at each stage)", "An autonomous agent (the model decides each stage and the order)", "Multi-agent (a specialist agent is placed at each of the stages)", "Manual work (no LLM; a person handles each stage in turn)"],
  a:[0], e:"Fixed steps call for a workflow." },
{ id:'ccarp-1-07', d:1, o:3, q:"In multi-agent orchestration, which responsibilities should the coordinator hold?",
  c:["Task decomposition, delegation, aggregating results, error handling, and control of information flow between subagents", "The internal implementation of each subagent (the model it uses, how it calls tools, the wording of its prompt)", "Updating the model weights, and the schedule of additional training carried out for each of the subagents", "Backing up the database, and the long-term storage of the output that each of the subagents has produced"],
  a:[0], e:"Hub and spoke: the coordinator is in control." },
{ id:'ccarp-1-08', d:1, o:3, q:"Choose the two costs and risks that correctly increase when you go multi-agent.",
  c:["More token consumption and more calls", "Information lost or garbled between agents", "A fall in the accuracy of the model itself", "Use of the API being suspended"],
  a:[0,1], e:"Multi-agent is not a cure-all. Cost and the complexity of passing information both go up." },
{ id:'ccarp-1-09', d:1, o:4, q:"You are designing a complex consistency check of internal regulations. Which decomposition approach fits?",
  c:["Split into verifiable stages: extract the rules → compare item by item → list contradictions → human check", "Put all the regulations into one prompt, ask it to find contradictions, and use the output as the report", "Rewrite the several regulations as a single document first, and then look for contradictions inside it", "Do not decompose; switch to a higher model and have it find every contradiction in a single call"],
  a:[0], e:"A decomposition that can be verified stage by stage raises quality and observability." },
{ id:'ccarp-1-10', d:1, o:4, q:"Which is the right way to think about the granularity of a decomposition?",
  c:["Split down to units whose output can be verified and tested, without going so fine that round trips pile up", "Split as finely as possible, so that each stage carries out one single operation and is certain to succeed", "Split as coarsely as possible, keeping the number of stages minimal to cut round trips and implementation", "Granularity does not affect the result, so developers may split in whatever way is easiest to implement"],
  a:[0], e:"It is a balance between verifiability and the cost of round trips." },
{ id:'ccarp-1-11', d:1, o:5, q:"What does it mean to align a proposed solution with the pillars of business value?",
  c:["State which of efficiency, transformation, productivity, cost or SLA you aim at and how to measure it, tied to the design", "Use fashionable technology (the newest models and frameworks) and present being advanced to executives as the value", "Put in as many features as possible, and judge which value users feel only after the system has been in use", "Leave value for later: build something that works first, and then think about how to explain it to executives"],
  a:[0], e:"Tie design decisions to measurable value." },
{ id:'ccarp-1-12', d:1, o:5, q:"There is a performance SLA of a response within 2 seconds. Which is the correct effect on the design?",
  c:["It constrains the design choices that affect latency: model choice, thinking depth, streaming, caching and the number of tool calls", "An SLA is an operational metric and does not affect design, so measure after the design is finished and set the SLA then", "With an SLA the top model becomes the only choice, since the other models lack the quality and leave no room to choose", "Batch processing is the surest way to meet an SLA, so drop the real-time responses and switch the system over to batch"],
  a:[0], e:"An SLA is a design constraint." },

// ---- Domain 2: Claude models, prompting and context engineering (13%) ----
{ id:'ccarp-2-01', d:2, o:0, q:"You proposed using Haiku for high-volume ticket classification and Opus for complex contract analysis. What is the right basis for this decision?",
  c:["Choose the model by difficulty, latency and cost, and send only the hard cases up a tier if needed", "Always use one model, because changing the model per task loses the consistency of the output", "Cheap models lack the quality and should be avoided; use only the higher models in production", "Try the models in alphabetical order of name, and keep using the first one that happens to work"],
  a:[0], e:"Tiered routing is a standard move for cost efficiency." },
{ id:'ccarp-2-02', d:2, o:0, q:"What should you have ready before choosing a model?",
  c:["An evaluation set of representative inputs and expected outputs, plus quality and cost criteria", "The vendor's marketing material, and the model's rank on the benchmarks that are published", "The developer's past experience, and a personal preference for the model they are used to", "Nothing in particular; decide by watching how things go while it is used in production"],
  a:[0], e:"Without an evaluation set you cannot show the basis for the choice." },
{ id:'ccarp-2-03', d:2, o:1, q:"Choose the two elements that should be included when you design a system prompt template.",
  c:["Role, purpose, output format, prohibitions, and behavior when unsure", "The boundary between untrusted data (input, documents) and instructions", "Personal information for each user, and the full history of past inquiries", "API keys, and the credentials and connection string of the target database"],
  a:[0,1], e:"Structure and boundaries are the skeleton of a template. Secrets and PII do not go in." },
{ id:'ccarp-2-04', d:2, o:1, q:"Can guardrails in the prompt alone guarantee that confidential data is never output?",
  c:["No. A prompt is probabilistic, so combine it with other layers such as output checks and tool permissions", "Yes. If the prohibitions are written clearly the model always obeys them, so nothing else is needed", "With a higher model, yes. A model that follows instructions faithfully does not break a prohibition", "With temperature 0, yes. The output becomes deterministic, so nothing that breaks a prohibition comes out"],
  a:[0], e:"Defense in depth." },
{ id:'ccarp-2-05', d:2, o:2, q:"For which task is prompting chain-of-thought especially effective?",
  c:["Multi-step reasoning, calculation, or branching decisions", "A simple classification that returns a one-word label", "Processing that copies a boilerplate text back as it is", "Processing that converts the file format of an image"],
  a:[0], e:"Having the model show its reasoning raises accuracy on multi-step problems. On easy tasks it only adds cost." },
{ id:'ccarp-2-06', d:2, o:2, q:"Which is the correct principle for designing few-shot examples?",
  c:["Prepare a few varied examples including ambiguous cases, showing the format and the reasoning", "Line up a large number of similar typical examples so the pattern is learned for certain", "Use personal information from production data as it is in the examples, to stay realistic", "One example is enough, and adding any more than that only becomes a cause of confusion"],
  a:[0], e:"Variety and the reasoning behind the decision help generalization." },
{ id:'ccarp-2-07', d:2, o:3, q:"When all 20 RAG search results were put into context, accuracy fell. What is the likely cause and the fix?",
  c:["Irrelevant chunks buried the key information. Rerank down to the top few, and put the important ones first", "Too few results were retrieved to include what is needed. Raise the count to 50 to cover everything", "The model in use is old and cannot pick information out of long context. Change to the newest model", "The chunks are too short and the context is cut. Lengthen them to raise the information in each one"],
  a:[0], e:"In context, quality matters more than quantity." },
{ id:'ccarp-2-08', d:2, o:3, q:"Choose the two measures that fit for optimizing token usage.",
  c:["Prune tool results and retrieved documents to the parts needed", "Cache the stable preamble (the system prompt)", "Send the whole conversation history every time, with nothing left out", "Always set the output length to the maximum, for detailed replies"],
  a:[0,1], e:"Pruning and caching are the basics." },
{ id:'ccarp-2-09', d:2, o:4, q:"An app sends an 8,000-token policy document every time. Which is the most direct measure that lowers latency and cost together?",
  c:["Place the static policy document before the dynamic content, and enable prompt caching", "Cut the policy document down to its first 1,000 tokens, and stop referring to the rest", "Change to the smallest model, to lower the unit price for the same number of tokens", "Rewrite the policy document as few-shot examples, and put them in the prompt each time"],
  a:[0], e:"Reusing the prefix lowers both cost and time to first token." },
{ id:'ccarp-2-10', d:2, o:4, q:"You want to reuse the same style guide for internal documents across several apps. Which mechanism fits?",
  c:["Manage the guide as a skill or a modular prompt component, and have each app reference it", "Copy the same guide text into each app's system prompt, and fix every app when it changes", "Have each developer memorize the guide, and write it in their own words in their prompts", "Keep the guide out of prompts, and use it as a checklist when people review the output"],
  a:[0], e:"Reuse strategies: caching, modular prompts and skills." },

// ---- Domain 3: Integration (19%) ----
{ id:'ccarp-3-01', d:3, o:0, q:"A support agent has tools to view tickets, draft replies, issue refunds and delete accounts, but the staff's job is only viewing and drafting. From a least-privilege standpoint, which change is best?",
  c:["Remove the refund and delete tools from the agent's configuration", "Keep detailed logs when a refund or deletion runs, so it can be traced", "Show a confirmation prompt before a refund or deletion, to make the model rethink", "Switch to a model that follows instructions better, to reduce mistaken runs"],
  a:[0], e:"Permissions that are not needed are removed, not monitored or confirmed." },
{ id:'ccarp-3-02', d:3, o:0, q:"Which is a fitting sign of capability bloat in an agent?",
  c:["Many tools unrelated to its role, causing wrong tool choices and a larger attack surface", "Only three tools, so that operations needed to carry out its role are missing", "Tool descriptions so detailed that they crowd the context and slow responses", "Permission controls on the tools that end up refusing even needed operations"],
  a:[0], e:"Keep tools to the minimum the role needs." },
{ id:'ccarp-3-03', d:3, o:1, q:"A Claude app calls an internal HR data API. Which authorization design is correct?",
  c:["The app verifies the end user's identity and permissions and propagates them to tool calls (the model does not decide permissions)", "The system prompt tells the model to answer only people with permission and refuse the rest, leaving the judgment to it", "Open the API to everyone so that all can do the same operations, and trace any misuse from the logs afterwards", "Since it is an internal app no authorization is needed, and everyone who can log in uses the tools with equal rights"],
  a:[0], e:"Authorization is the responsibility of the app and the API. The model can be bypassed." },
{ id:'ccarp-3-04', d:3, o:1, q:"An MCP server accesses all data through a shared service account. What is the security gap?",
  c:["Per-user permissions are not reflected, so data a user should not see is visible (privilege escalation)", "Using a shared account slows the processing down, and responses take a longer time to come back", "A shared account produces more logs, which raises the cost of storage and the effort of auditing", "There is no gap; a shared account is a standard and safe configuration for internal applications"],
  a:[0], e:"Confusing privileges through shared credentials is a common design mistake." },
{ id:'ccarp-3-05', d:3, o:2, q:"Adding extended thinking and reranking to raise accuracy pushed responses to 6 seconds, over the 3-second SLA. Which is the right decision for the architect?",
  c:["Split by request type: a light path for simple ones, the heavy path only for complex ones, and show the basis", "Put accuracy first, treat the SLA as a stretch goal, and handle the delay by explaining it to the users", "Put the SLA first, lower the accuracy requirement, and run with people fixing the errors afterwards", "Show users a progress indicator and have them wait, running as is with accuracy and SLA unchanged"],
  a:[0], e:"The answer is to make the trade-off visible and route." },
{ id:'ccarp-3-06', d:3, o:2, q:"Tool-call round trips rose by 2–3 per task and latency by 40%. Evaluation shows that 85% of verifications are simple fact checks. Which configuration is best?",
  c:["Give a lightweight tool for simple checks, and send only the remaining 15% of deep research via the coordinator", "Send every check through the coordinator, and give the synthesis agent no means of checking by itself", "Stop verifying in the synthesis agent, and leave the checking to the person who reads the final report", "Send every case down the deep research path, putting accuracy first and accepting the added latency"],
  a:[0], e:"Optimize for the majority case, and give the minority a separate path." },
{ id:'ccarp-3-07', d:3, o:3, q:"You operate hundreds of agent runs. Choose the two things needed at a minimum for observability.",
  c:["Per-request traces (prompt, tool calls, response, latency)", "Dashboards and alerting for quality, cost and error rate", "Posting every full output to a Slack channel for all to read", "Keeping no logs, and reproducing problems on the spot"],
  a:[0,1], e:"Traces and aggregate metrics." },
{ id:'ccarp-3-08', d:3, o:3, q:"In large-scale operation, which should not be included in logs?",
  c:["Raw personal information and secrets (things that need masking)", "The breakdown and the total of input and output token counts", "A record of latency and processing time for each request", "The names of the tools called and the types of their arguments"],
  a:[0], e:"Observability and privacy have to coexist." },
{ id:'ccarp-3-09', d:3, o:4, q:"Which is the right way to think when deciding a chunking strategy for RAG?",
  c:["Cut by units of meaning to suit the document structure and the queries, adding overlap or metadata if needed", "Always cut mechanically at a fixed 500 characters whatever the document, with no overlap and no metadata", "Always index the whole document as one chunk, and have the search return the matching document entire", "Decide the chunk boundaries at random, and cancel out the effect of the cuts by retrieving more results"],
  a:[0], e:"Fit the shape of the data." },
{ id:'ccarp-3-10', d:3, o:4, q:"After a document update, RAG began returning confident but wrong answers. Neither the model nor latency has changed. What should you examine first?",
  c:["Whether the retrieval and indexing stage is returning irrelevant or stale chunks", "Whether the vendor changed the model weights and answer quality has dropped", "Whether the temperature is set too low and answers have become too cautious", "Whether the context window limit shrank and the context no longer fits in"],
  a:[0], e:"When behavior changes right after the documents change and nothing else has, suspect retrieval first." },
{ id:'ccarp-3-11', d:3, o:5, q:"There are two kinds of query: look up a spec by product ID, and find similar cases from natural language. Which search strategy fits?",
  c:["Structured (keyword or exact match) for ID lookups, vector search for natural language, and hybrid as needed", "Vector search for everything, embedding the product IDs too so one implementation finds them by similarity", "Keyword search for everything, rephrasing natural language through a synonym dictionary into search terms", "No search at all: put all the product data into context and have the model find the matching product"],
  a:[0], e:"Fit the query pattern." },
{ id:'ccarp-3-12', d:3, o:5, q:"Many questions are about tabular data (sales line items). Which approach suits better than RAG?",
  c:["Run a structured query such as SQL through a tool, and pass the result", "Convert each row to text, embed it, and find it by vector search", "Turn the table into a screenshot and pass it in as an image input", "Ordinary RAG is enough, so split the table into chunks and search"],
  a:[0], e:"If the data is structured, use a structured query." },
{ id:'ccarp-3-13', d:3, o:6, q:"Several internal teams use the same customer API from Claude. Which integration mechanism fits?",
  c:["Publish it as an MCP server, and reuse it across the teams", "Each team writes its own script that calls the CLI", "Each team pastes the data into prompts by hand", "Skip the API, and automate the screens to fetch data"],
  a:[0], e:"For standardized reuse, MCP." },
{ id:'ccarp-3-14', d:3, o:6, q:"You need to hand tasks over in cooperation with another company's agent. Which integration mechanism should you consider?",
  c:["Define an agent-to-agent protocol and contract, making inputs, outputs and the scope of responsibility clear", "Copy the other agent's system prompt into your own agent, so that the two of them behave in the same way", "Have the other side share its agent's API key, and call its tools directly from inside your own agent", "Cooperation with another company's agent is too risky, so avoid it and have people exchange the data by hand"],
  a:[0], e:"Assess which fits: MCP, API/CLI, or agent-to-agent." },
{ id:'ccarp-3-15', d:3, o:7, q:"Compare the all-at-once approach, giving an agent 200 tools and every document from the start, with progressive discovery, letting it find them as needed. Which is correct?",
  c:["All-at-once crowds the context and lowers selection accuracy. Progressive is context-efficient but adds discovery round trips", "All-at-once is always better. Every tool and document is visible from the start, so the model's judgment is most accurate", "Progressive is always better. It saves context, so at any scale it is faster and cheaper than the all-at-once approach", "There is no difference. Whichever you choose, tokens and round trips come out the same, and accuracy is not affected"],
  a:[0], e:"Choose with the trade-off understood. MCP resources and skills are examples of progressive loading." },
{ id:'ccarp-3-16', d:3, o:7, q:"When is progressive discovery especially effective?",
  c:["There are many documents and tools, and a single task uses only part of them", "There is only one document, and every one of the tasks refers to that document", "Every document and every tool is always used in each and every task", "Latency comes first, and round trips for discovery cannot be added"],
  a:[0], e:"It suits a large catalog with a low usage rate." },

// ---- Domain 4: Evaluation, testing and optimization (16%) ----
{ id:'ccarp-4-01', d:4, o:0, q:"Which is a fitting set of evaluation metrics for a customer support summarization app?",
  c:["Accuracy, latency, cost, safety (rate of inappropriate output) and security (resistance to injection)", "The name and version of the model in use, and its rank and score on vendor-published benchmarks", "The average output length in characters, the paragraphs per item, and the range of vocabulary used", "The satisfaction of developers and the product owner, and a tally of opinions from team meetings"],
  a:[0], e:"Define along several axes." },
{ id:'ccarp-4-02', d:4, o:0, q:"What should be decided before setting a target of 95% accuracy?",
  c:["The definition of accuracy (what counts as correct), how to measure it, error weights", "The name of the model to be used, and that model's rank on the public benchmarks", "The design of the screen that shows the results, such as its colors and layout", "Nothing in advance; think about what accuracy means while running in production"],
  a:[0], e:"A metric comes as a set with its definition and its way of measuring." },
{ id:'ccarp-4-03', d:4, o:1, q:"Choose the two fitting ways to build an evaluation dataset.",
  c:["Include real data close to production (anonymized), and edge cases", "Combine human labeling with LLM grading, and verify the grading by people", "Collect only the easy, typical examples the developers can think of", "Use no production data at all, and build it from synthetic data alone"],
  a:[0,1], e:"A combination of several methods." },
{ id:'ccarp-4-04', d:4, o:1, q:"Which is the correct caution when using an LLM as a judge?",
  c:["State the grading criteria, and verify agreement with human judgment before use", "LLM grading is always correct, so verification by people is not needed", "Make the grading prompt the same as the prompt that is being graded", "Write no criteria, and let the LLM grade by its own general judgment"],
  a:[0], e:"LLM grading needs calibration too." },
{ id:'ccarp-4-05', d:4, o:2, q:"Which is the most reliable way to check whether a new prompt is better than the old one?",
  c:["Run both on the same evaluation set and compare the metrics. In production, A/B test on a portion", "A developer tries a few inputs, compares the outputs, adopts the one that feels better, and rolls it out", "Roll the new version out to all users, and judge it improved if the number of complaints does not rise", "Survey the users, and decide by majority vote which of the two prompts gives the better output"],
  a:[0], e:"Offline evaluation plus staged A/B." },
{ id:'ccarp-4-06', d:4, o:2, q:"An A/B test shows the new version is 2% more accurate but 40% more expensive. Which is the right decision for the architect?",
  c:["Compare the business value of the 2% gain with the added cost, and if needed send only hard cases to the new version", "Always adopt the more accurate one. Quality should come before cost, and even a 2% difference is worth adopting", "Always adopt the cheaper one. Users cannot tell a 2% difference, and the cost difference matters more to management", "The test conditions may have been flawed, so rebuild the evaluation set and run the whole test over again"],
  a:[0], e:"Judge a trade-off by value." },
{ id:'ccarp-4-07', d:4, o:3, q:"Output that is not factual has increased. Which is the right order for isolating the cause?",
  c:["Check in order: input (the retrieved context) → prompt (a change to instructions) → model (a version change)", "Switch to a higher model first, confirm in production whether hallucination falls, then consider the cause", "Add an instruction to the prompt to answer on the basis of facts, making it longer, and see how it goes", "Hallucination is in the nature of an LLM, so do not chase the cause; handle it by adding human review"],
  a:[0], e:"Diagnosing hallucination, prompt failure and model mismatch." },
{ id:'ccarp-4-08', d:4, o:3, q:"On a certain task a lightweight model's accuracy does not meet the requirement. Which is a way to handle this possible model mismatch?",
  c:["Try a higher model on the evaluation set, and if needed route only the hard cases up", "Keep adjusting the prompt, iterating with the same model until accuracy rises", "Lower the accuracy requirement to a level that can be met, and keep the model", "The current model cannot do it, so give up on automating this task"],
  a:[0], e:"The limits of a model's ability are hard to get past with a prompt." },
{ id:'ccarp-4-09', d:4, o:4, q:"Choose the two measures with a large effect on lowering cost.",
  c:["Making use of caching and the Batch API", "Routing between models by task difficulty", "Keeping output length at the maximum setting", "Running everything synchronously on the top model"],
  a:[0,1], e:"Caching, batch and routing." },
{ id:'ccarp-4-10', d:4, o:4, q:"A breakdown of latency shows that time to first token is long. Which improvement fits?",
  c:["Cut input tokens and cache them, use streaming, and review the depth of thinking", "Instruct shorter output, reducing the characters in a response so it feels faster", "Change to a larger model so one response completes the work with fewer round trips", "Shorten the timeout and raise the number of retries, adopting only fast responses"],
  a:[0], e:"Time to first token depends on input processing." },
{ id:'ccarp-4-11', d:4, o:5, q:"Which monitoring should be set up to detect a drop in production quality early?",
  c:["Time series of quality (sample grading), error rate, latency and cost, with threshold alerts", "Once a month, a member of staff looks over a few outputs by eye to see if anything is wrong", "Record only the number of complaints from users, and look into the cause when it rises", "After the release do no particular monitoring, and respond when an incident happens"],
  a:[0], e:"Continuous observation." },
{ id:'ccarp-4-12', d:4, o:5, q:"Which is the fitting information to keep for each request in logging?",
  c:["Prompt version, model ID, token counts, tool calls, latency and evaluation", "User passwords and auth tokens, and the session secret key with its expiry", "Keep no logs at all, as a policy to avoid privacy and storage cost issues", "The developers' impressions of the output, and notes on what to improve"],
  a:[0], e:"The information needed to reproduce and analyze." },

// ---- Domain 5: Governance, safety and risk management (14%) ----
{ id:'ccarp-5-01', d:5, o:0, q:"You are designing guardrails for a medical intake assistant app for a healthcare provider. Which combination of layers fits?",
  c:["Input checks, policy in the system prompt, output checks (no definitive diagnoses), and handoff to a person at high risk", "Write the medical cautions carefully in the system prompt, place no other layers, and leave it to the model's judgment", "Place output checks only, and implement no input checks, no system prompt policy and no handoff to a person", "Health information is general content, so guardrails are unnecessary and it can be offered as an ordinary chat"],
  a:[0], e:"Guardrails in several layers." },
{ id:'ccarp-5-02', d:5, o:0, q:"Where is the right place to put a mechanical check on output safety?",
  c:["Before model output is returned to the user (post-processing), and before a tool runs", "After the output has been returned to the user, sending a correction if there is a problem", "Nowhere at all; control it only through the instructions in the model's prompt", "In the middle of the model's internal reasoning, stopping the generation itself"],
  a:[0], e:"Stop it before returning and before executing." },
{ id:'ccarp-5-03', d:5, o:1, q:"Choose the two that are correct as typical failure modes of an LLM system.",
  c:["Hallucination (plausible errors)", "Instructions hijacked by prompt injection", "CPU overheating from the inference load", "Disk fragmentation from accumulated logs"],
  a:[0,1], e:"Know the risks particular to LLMs." },
{ id:'ccarp-5-04', d:5, o:1, q:"The model is non-deterministic, and output varies for the same input. What operational risk does this bring?",
  c:["Reproducibility and testing get harder. Design evaluation with repeated runs and statistical criteria", "There is no risk. The content is the same even if the output varies, so a single test run is enough", "The output is always wrong. A model with non-determinism cannot be put to use in production", "The model stops. When the non-determinism is high, the requests sent to it end up failing"],
  a:[0], e:"Designing for non-determinism." },
{ id:'ccarp-5-05', d:5, o:2, q:"Which is a fitting human-in-the-loop design?",
  c:["Send high-risk decisions, low-confidence output and irreversible operations to human approval, and keep the decisions as feedback", "People check every output before it is used, no path flows downstream automatically, and human review is mandatory for all", "Keep people out of it and use the model's output as it is, with people responding after the fact only when a problem occurs", "People only look at the results, with no approving or correcting, and the judgment on model output is left to the system"],
  a:[0], e:"Narrow what is reviewed, and return the decisions to learning." },
{ id:'ccarp-5-06', d:5, o:2, q:"Which is a fitting way to lower the human review load while keeping safety?",
  c:["Route by confidence and risk, automate high-confidence low-risk cases, and audit by stratified sampling", "Abolish review, use the model's output as it is, and learn of problems from what users point out", "Review every item, and deal with any growth in volume by adding to the number of reviewers", "Look at a random half only, and let the other half flow downstream as it is without checking"],
  a:[0], e:"Routing and auditing." },
{ id:'ccarp-5-07', d:5, o:3, q:"For an app handling personal data of EU residents (subject to GDPR), what should be confirmed at design time?",
  c:["The purpose of processing, where and how long data is stored, handling of deletion requests, and vendor contracts", "The color theme of the screens, and switching the display language to suit the region of each of the users", "The name of the model to be used, and the list of the languages that this particular model supports", "Nothing in particular needs confirming; it can be offered as is, configured like any ordinary application"],
  a:[0], e:"Turn regulatory requirements into design." },
{ id:'ccarp-5-08', d:5, o:3, q:"When data subject to HIPAA (the US health information regulation) is processed with Claude, which premise should the architect confirm?",
  c:["Whether the vendor contract (a BAA, for example) permits processing protected information, and control of logs", "The response speed of the model, and the latency to be expected when used on the provider's own network", "Whether the colors and the size of the text in the UI are easy to read for users at the healthcare provider", "Nothing in particular; the premise is that it can be offered as is, configured like any ordinary app"],
  a:[0], e:"Confirm the contractual and control premises before designing." },
{ id:'ccarp-5-09', d:5, o:3, q:"A FedRAMP requirement came up in a project for a US government agency. Which response by the architect fits?",
  c:["Confirm that an authorized offering (through a cloud platform, for example) is available, and reflect the data boundary in the design", "The requirement is a formality, so ignore it, build with the same configuration as for the private sector, and respond when asked", "Use the same configuration as for the private sector; authorization is the vendor's concern and is not considered in your design", "Changing the model settles it: just choose an authorized model, with no need to consider the offering or the data boundary"],
  a:[0], e:"Compliance leads straight to the choice of offering." },
{ id:'ccarp-5-10', d:5, o:4, q:"For using an LLM in hiring screening, what should be built into the design on the ethics side?",
  c:["Assessment of bias by attribute (fairness testing), transparency of reasons, and a person making the final call", "Automate the screening completely, securing fairness by removing the subjectivity of people from it", "Show no reasons for a decision and output only the result, so that no bias can be pointed out", "Skip the bias assessment, on the premise that the model is fair because its training data is broad"],
  a:[0], e:"Bias, fairness and transparency." },
{ id:'ccarp-5-11', d:5, o:4, q:"Which is a fitting practice of transparency toward users?",
  c:["Tell users clearly that AI is involved, along with its limits and a point of contact", "Hide that AI is involved, and make it look as though a person is responding", "Show that AI is involved, but do not show its limits or a point of contact", "Do nothing in particular, and offer it with the same guidance as any service"],
  a:[0], e:"Transparency is a pillar of responsible AI." },

// ---- Domain 6: Stakeholder communication and lifecycle management (14%) ----
{ id:'ccarp-6-01', d:6, o:0, q:"Choose the two kinds of information that should be drawn out of stakeholders at the discovery stage.",
  c:["The current business flow, bottlenecks, and the definition of success (metrics)", "Where the data lives, its confidentiality class, and touchpoints with existing systems", "The name of the model they want to use, and the plan they are contracted on", "The programming language and the framework that the developers like best"],
  a:[0,1], e:"Gather the premises about the work, the metrics and the data systematically." },
{ id:'ccarp-6-02', d:6, o:0, q:"In requirements gathering, a vague request came up: leave everything to AI. Which response by the architect fits?",
  c:["Break it into concrete business scenarios, and define success criteria, risk tolerance and human involvement together", "Accept the demand to automate everything as it stands, and start building within the range that is technically possible", "Refuse, since everything is technically impossible, and do not start the project until the demand becomes concrete", "Do not point out the vagueness; set the scope by the architect's own reading and quietly start building"],
  a:[0], e:"Structured discovery." },
{ id:'ccarp-6-03', d:6, o:1, q:"You are telling executives about the decision to choose a workflow and not an autonomous agent. Which way of telling it fits?",
  c:["Show briefly the options, the trade-offs (predictability, cost, risk), the reason for the decision, and when to revisit it", "Explain the design details in technical terms, so that executives understand the mechanism before they make a judgment", "Give no reason for the decision; convey only the conclusion, and answer any questions one by one as they come", "Keep the content of the decision back, and report to executives after implementation ends and results are in"],
  a:[0], e:"Communicating an architecture decision." },
{ id:'ccarp-6-04', d:6, o:1, q:"Which elements should an architecture decision record (ADR) include?",
  c:["Context, the options considered, the decision, and the consequences (trade-offs)", "The full text of the implemented code, and the contents of the config files", "The impressions of those involved, and the mood of the meetings on the way", "Keep no record, and share only what was decided by word of mouth"],
  a:[0], e:"A record of the decision pays off when it is revisited later." },
{ id:'ccarp-6-05', d:6, o:2, q:"A stakeholder demanded 100% accuracy. Which response fits?",
  c:["Explain that 100% cannot be guaranteed, and turn it into an SLA with measurable targets and human checks", "Promise 100% accuracy as demanded, and deal with any shortfall later by renegotiating the contract", "Ignore it as an impossible demand, with the architect setting a realistic target and moving ahead", "Since a project that demands 100% cannot stand, propose that the project be cancelled"],
  a:[0], e:"Adjusting expectations, and an SLA." },
{ id:'ccarp-6-06', d:6, o:2, q:"Which is a fitting design for the feedback loop after operation begins?",
  c:["Share metrics and user voices in regular review meetings, and agree on improvement priorities", "Treat the project as complete once released, and accept no feedback from then on", "Respond only when users complain, with no regular forum for sharing or agreement", "Collect no feedback; improve on the development team's judgment from metrics alone"],
  a:[0], e:"Continuous adjustment of expectations." },
{ id:'ccarp-6-07', d:6, o:3, q:"Choose the two things that should be included in the handoff document for the implementation team.",
  c:["Architecture diagram, component responsibilities, data flow and integration points", "Prompt versions, the evaluation set, and runbooks (monitoring and rollback)", "The developers' private views, and a list of their personal opinions on the design", "The small talk from design meetings, and a record of topics left undecided"],
  a:[0,1], e:"Implementation guidance, and the information operation needs." },
{ id:'ccarp-6-08', d:6, o:3, q:"Which is recommended for handling prompts in documentation?",
  c:["Version-control the prompts, noting the reason for each change and the evaluation results", "Do not document prompts; treat whatever is in the code as the source of truth", "Pass prompts on by word of mouth, explaining them at the time of the handoff", "Keep only the latest version and erase the history, to keep the documents brief"],
  a:[0], e:"Prompts are design assets." },
{ id:'ccarp-6-09', d:6, o:4, q:"Which role does the architect play in the monitoring phase of the lifecycle?",
  c:["From the monitored metrics, judge whether a model update, prompt revision or configuration change is needed, and lead into iteration", "Do nothing in particular once it is in production, and respond when the development team makes contact about a problem", "Leave operation to the developers; the architect's role ends at the design stage, with no involvement from then on", "Move on to the next new project, and leave improvement of the running system to the judgment of those in charge"],
  a:[0], e:"Discovery → design → handoff → monitoring → iteration." },
{ id:'ccarp-6-10', d:6, o:4, q:"A new version of the model has come out. Which procedure fits as lifecycle management?",
  c:["Regression test on the evaluation set → adjust the prompts → switch over in stages → monitor", "Switch over fully the moment a new model appears, and go back if there is a problem", "Do not switch while the old model still works, and deal with it when it is retired", "Let users choose between the old and new models, leaving the decision to each user"],
  a:[0], e:"The standard move in the iteration phase." },

// ---- Domain 7: Developer productivity and operational support (7%) ----
{ id:'ccarp-7-01', d:7, o:0, q:"You want the whole development team to use Claude Code in the same way. What should be put in place first?",
  c:["The repository's CLAUDE.md and shared settings under `.claude/` (permissions, commands, skills)", "Each developer writing the conventions for themselves into their personal settings (`~/.claude/`)", "Verbal rules passed on in meetings, kept by each person and not written into any settings file", "Nothing in particular, so that each developer can use Claude Code in the way they like best"],
  a:[0], e:"Team configuration is shared through version control." },
{ id:'ccarp-7-02', d:7, o:0, q:"Which setting fits for keeping Claude Code from operating on production across the team?",
  c:["Deny dangerous commands with `settings.json` permissions or with hooks", "Write in CLAUDE.md that care should be taken with dangerous commands", "Have developers check before running, with no restriction in settings", "Ban the use of Claude Code in the team, because it is dangerous"],
  a:[0], e:"Deterministic control belongs in settings and hooks." },
{ id:'ccarp-7-03', d:7, o:1, q:"When improving developer workflows with AI-assisted tools, where does the effect come most readily?",
  c:["Routine code generation, test writing, documentation, and a first-pass check in review", "The final call on the design of the whole system, and approval of architecture decisions", "Approval of deployment to production, and the final decision and notice of a release", "Performance reviews of the developers, and decisions on team placement and promotion"],
  a:[0], e:"Start with work that is repetitive and verifiable." },
{ id:'ccarp-7-04', d:7, o:1, q:"AI code review was introduced, but false positives led developers to start ignoring it. Which response by the architect fits?",
  c:["State the review criteria, and pause the categories with many false positives to win back trust while improving", "Stop the automated review; now that developers no longer trust it, go back to running on human review alone", "Order developers not to ignore the findings of the automated review, and make responding to them mandatory", "Raise the number of findings for more coverage, lifting the odds that the important ones are among them"],
  a:[0], e:"Keeping trust decides whether an introduction succeeds." },
{ id:'ccarp-7-05', d:7, o:2, q:"Responses from a Claude app in production suddenly became slow. What should operational support look at first?",
  c:["Isolate the stage with traces and metrics (input tokens, number of tool calls, latency, retries)", "Switch to a lighter model first, see in production whether latency recovers, then seek the cause", "Restart the agent process, and if latency recovers, simply keep operating and see how it goes", "Shorten the system prompt to reduce the input, and see whether the latency comes back to normal"],
  a:[0], e:"Isolation based on observability." },
{ id:'ccarp-7-06', d:7, o:2, q:"A developer reported that tool results are not reaching the model. Which support fits?",
  c:["Look at how the tool_use_id values match up in the logs, to isolate integration layer from model output", "Conclude that it is a model bug, report it to the vendor, and stop using tools until it has been fixed", "Have the system prompt rewritten with a stronger instruction to always use tool results, then wait and see", "Give up, since the cause is hard to pin down, and have a person step in when a tool result is not used"],
  a:[0], e:"The basis of debugging is isolation." },
// ---- Added from study notes ----
{ id:'ccarp-1-13', d:1, o:0, q:"Which is the recommended order for the four things to decide before building?",
  c:["Which part of the work Claude takes on → the shape of the work (single call, workflow or agent) → the reference architecture to build on → where it touches (entry point, model, context strategy)", "Model tier → delivery route (Bedrock or Vertex AI) → how the prompts are written → design of evaluation. The model is decided first, because without it no cost estimate can be made", "Entry point (Claude.ai or your own app) → context strategy → the number of primitives used → which part of the work Claude takes on. Decide by working back from the user's experience", "Budget ceiling → latency target → safety layers → the way of decomposing. If the non-functional requirements are fixed first, any pattern can be chosen with no change of course later"],
  a:[0], e:"Getting the order wrong means an expensive change of course. The part Claude takes on → the shape of the work → the reference architecture → the touchpoints." },
{ id:'ccarp-1-14', d:1, o:0, q:"You received a report that the demo worked five times. Which is the correct position?",
  c:["Working five times is no proof of being deterministic. Non-determinism is the premise, so measure behavior on an evaluation set and then judge", "Five successes in a row mean the same behavior can be expected in production, and building an evaluation set can wait for the improvement phase", "Raise the number of demo runs to 20, and if all succeed treat it as deterministic and switch to operating without creating an evaluation set", "Setting temperature to 0 makes the output deterministic, so fixing the settings with which the demo succeeded makes evaluation unnecessary"],
  a:[0], e:"What follows from Claude's nature: non-determinism means evaluation is needed, and confidence is not correctness." },
{ id:'ccarp-1-15', d:1, o:1, q:"Which is the correct account of the three layers of a deployment?",
  c:["Entry point (what people or systems touch), build-time interface (API, SDK, MCP) and delivery route (where traffic terminates) do not replace each other; every deployment has all three", "Entry point, build-time interface and delivery route are exclusive; choosing Claude Code as the entry point removes the choice of delivery route and the cloud contract", "If MCP is chosen as the build-time interface, the entry point and delivery route are settled on the MCP server side, so the layers the architect chooses fall to one", "The delivery route is a layer for compliance alone and does not affect latency or when features arrive, so settle it mechanically after the other two are decided"],
  a:[0], e:"The entry point is chosen for the users and the work, the interface for the development team, and the delivery route for the cloud contract and compliance." },
{ id:'ccarp-1-16', d:1, o:1, q:"A stock inquiry chat answered “in stock” when the item was in fact sold out. The cause was that the stock table had been indexed for RAG. Which is the right fix?",
  c:["Fetch current state from the stock system through a tool call. Retrieval is for stable knowledge, and better embeddings or a shorter refresh interval will not fix this", "Shorten the index refresh interval from one hour to five minutes and move to a higher embedding model; with better retrieval, missed sell-outs fall far enough", "Make the chunks of the stock table smaller, index it row by row, and add hybrid search and reranking, so that the newest row reliably comes out on top", "Write in the system prompt that stock must be checked against the latest source and never reported as in stock when unsure, leaving restraint to the model"],
  a:[0], e:"The most common mistake is using retrieval for live state. Orders, stock and balances are tool calls." },
{ id:'ccarp-1-17', d:1, o:2, q:"Which are the five factors to look at in order when choosing a pattern?",
  c:["Predictability → cost of error → observability → latency budget → cost. The first factor that rules a pattern out is the decider", "Cost → latency budget → model tier → number of tools → number of users. Try from the cheapest upward to stay inside the budget", "Users' technical level → entry point → delivery route → observability → maintainability. Decide from the human side inward", "Cost of error → regulation → team experience → future extensibility → cost. Put future flexibility first and choose an agent"],
  a:[0], e:"Look at the five factors in order and let the first one that rules something out decide. Do not choose an agent for the sake of future flexibility." },
{ id:'ccarp-1-18', d:1, o:2, q:"An agent was proposed on these grounds: requests fall into four kinds, the steps for each are fixed, but which one will arrive is unknown, so it is uncertain. Which assessment is sound?",
  c:["Feeling uncertain differs from being unable to fix the steps in advance. If the paths stay within four, a router and four chains are enough", "Not knowing which will arrive is the same as being unable to fix the steps in advance, so an agent with restricted tools is the sound choice", "Putting the four procedures into one system prompt as an augmented LLM call is simplest, with no need for either a router or an agent", "A fifth kind may be added in future, so making it an agent now avoids changing the design every time a procedure is added"],
  a:[0], e:"Start from the simplest thing that meets the requirements, and step up only when measurement shows a shortfall. Routing is one of the workflow patterns." },
{ id:'ccarp-1-19', d:1, o:3, q:"An orchestrator hands 12 documents to subagents and collects summaries. Which check should always be made at synthesis?",
  c:["Match the number of results returned against the number of units sent out (a coverage check), and re-delegate any that are missing", "Put all of the summaries into a single prompt, and have the orchestrator summarize the whole set over again from the beginning", "Compare the time each subagent took, and drop the slowest one from the next run onward in order to raise the parallelism", "Check that the summaries are all of the same length, and have the same subagent add more to any that turn out short"],
  a:[0], e:"Units that were fanned out are counted against results at synthesis. A subagent failure is often recoverable, but a gap is invisible unless the synthesis side detects it." },
{ id:'ccarp-1-20', d:1, o:4, q:"Claims processing has a rule that claims over 100,000 yen need a manager's approval. Which decomposition is right?",
  c:["Keep the threshold routing in a rules engine or code, and use Claude for extracting the amount and drafting. A model judging an amount written in words gets it wrong", "Write the threshold in the system prompt and have Claude decide that anything above 100,000 yen goes to a manager. With only one rule it will be followed well enough", "Leave the threshold decision to Claude as well, but reduce mistakes by adding few-shot examples of notation variants for the amount, in digits and in words", "Leave both extracting the amount and the routing to Claude, and find and fix mistakes in an audit afterwards. The rules engine then no longer needs maintaining"],
  a:[0], e:"Do not move deterministic business rules into a prompt. Think of decomposition in terms of three owners: Claude, existing systems and people." },
{ id:'ccarp-1-21', d:1, o:5, q:"Which is the correct handling of a feasibility verdict and ROI?",
  c:["Three verdicts: feasible as is, feasible with constraints, infeasible. Document constraints as part of the design, and treat “infeasible” as a sound assessment that avoids a costlier failure", "Two verdicts: feasible or infeasible. “Infeasible” is a lost sale and so to be avoided; answer “feasible” with constraints to any requirement, and negotiate those constraints afterwards", "ROI is the POC bill multiplied by the number of months in production. Even where human review remains, the benefit may be estimated on the premise of full automation in the future", "ROI may be shown from the post-deployment forecast alone, with the current baseline measured after deployment. The payback period is put as one single figure with no sensitivity analysis"],
  a:[0], e:"ROI compares the current baseline with the forecast in the same unit of work, subtracts running cost, and shows the payback period with sensitivity. If human review is needed, do not assume full automation." },
{ id:'ccarp-2-11', d:2, o:0, q:"Which is the recommended starting point for model selection in a new project?",
  c:["Start with Sonnet; move to Opus if evaluation shows quality is short, and to Haiku once evaluation confirms it is acceptable", "Start with the top model and step down while watching the production bill; failing on cost is safer than failing on quality", "Start with Haiku and move up when users complain; the count of complaints stands in for evaluation and saves building a set", "Use all three models in production at once, assigned to users at random, and narrow to one by a satisfaction survey"],
  a:[0], e:"Not choosing a model is the same as choosing the most expensive one. Move on the basis of evaluation." },
{ id:'ccarp-2-12', d:2, o:0, q:"Someone proposes leaving extended thinking on because it can do no harm. Which assessment is right?",
  c:["Extended thinking trades cost and latency. Evaluate without it first, and enable it only for a measured shortfall in accuracy", "If there is even a slight chance that multi-step reasoning is needed, enabling it from the start is cheaper than fixing later", "Extended thinking does not add input tokens, so it has no effect on cost, and the decision can be made on latency alone", "Enabling extended thinking makes evaluation results stable, so the right order is to turn it on before evaluating"],
  a:[0], e:"Do not enable it on the grounds that it can do no harm." },
{ id:'ccarp-2-13', d:2, o:1, q:"For the same request, the output format and assumptions differ every time. Which explanation is closest?",
  c:["Under-specification: gaps the model fills with a different assumption each time. Write the role and scope, constraints and output contract, and leave legitimate variation in", "An unavoidable effect of the model's non-determinism. Beyond setting temperature to 0 and normalizing the output in post-processing nothing can be done; revising the prompt will not fix it", "The system prompt is too long. Cutting the instructions to three lines or fewer aligns the assumptions; the more constraints are added, the more contradictions arise and the less stable it gets", "There are too few few-shot examples. With 20 or more examples for the same request, format and assumptions converge on the examples, and there is no longer any need to write a contract"],
  a:[0], e:"A prompt is a designed artifact. Diagnose under-specification, and choose a revision that constrains scope, format and behavior." },
{ id:'ccarp-2-14', d:2, o:2, q:"Techniques should be applied lightest first. What is that order, and where does structured output fit?",
  c:["Zero-shot → few-shot → step-by-step reasoning. Fix a format problem with structured output, and a judgment problem with better examples or instructions", "Step-by-step reasoning → few-shot → zero-shot, adopting whichever scores the highest accuracy. Structured output is the tool to use for judgment problems", "Few-shot by default, and zero-shot only when examples cannot be gathered. Structured output fixes both format and judgment, so it goes in first", "Native thinking by default, and few-shot only for models that lack it. Structured output adds to latency, so it is kept as the last resort"],
  a:[0], e:"Apply the technique that fits the observed type of failure, with no unnecessary token cost." },
{ id:'ccarp-2-15', d:2, o:2, q:"Which correctly explains the difference between having the model think step by step through the prompt and native thinking (extended thinking)?",
  c:["In the first, reasoning is generated as part of the output. In the second, the model reasons separately as a feature, with depth tuned by effort. A simple task needs neither", "The two are different names for one mechanism, and both return reasoning as output tokens. If the model supports it, always use the second; cost and latency do not differ", "The first costs nothing and the second costs money. So even for tasks that need multi-step reasoning, make do with the first and hold the second back as a last resort", "The second is a feature that guarantees the output format, so use it for broken formats. The first lifts the quality of judgment; their roles do not overlap and cannot be combined"],
  a:[0], e:"Where multi-step reasoning is needed and the model supports thinking, the second is the default. Structured output is a separate feature for format problems." },
{ id:'ccarp-2-16', d:2, o:3, q:"In a long-running agent, old tool results are crowding the context. You want to keep the course of the conversation itself. Which choice uses the right mechanism for each need?",
  c:["If old tool output is only taking up room, drop it with context editing. Use compaction to shrink the history into a summary, and the memory tool to keep things across sessions", "Replace the whole with a summary through compaction. There is no mechanism that drops tool output alone, so summarize the history too and fetch again whatever has been lost", "Write all the old tool output out to the memory tool and erase it from context. Memory has no capacity limit, so this is the safest choice and keeps the history as well", "Do nothing until the context window limit arrives. The limit is a target, so use it up before considering the next move, and start a new session once it has been passed"],
  a:[0], e:"The window is a ceiling, not a target. A long-running agent combines the three." },
{ id:'ccarp-2-17', d:2, o:3, q:"A cost estimate used an average of 2,000 tokens per request. Which criticism is correct?",
  c:["Token distributions are skewed. An estimate from the average is off by 2–3×, so budget from the distribution, and design latency to p95 and not the median", "The average is a good enough representative of the distribution, with error within 20–30%. Design latency on the average too, absorbing outliers by retries and timeouts", "Token counts are set by input length, so estimating from the longest input is safe. Design latency to the maximum too, and reserve the budget to match that upper bound", "The estimate can simply be the POC bill multiplied by the months in production, with no need to study the token distribution. For latency, the POC measurements are enough"],
  a:[0], e:"Sizing goes: call volume → per-request budget (from the distribution) → monthly cost → sensitivity analysis." },
{ id:'ccarp-2-18', d:2, o:4, q:"Which is the principle for ordering a prompt so that caching works best?",
  c:["Fixed content (role, rules, reference documents) first and changing content (user input) last, with the breakpoint placed after the stable part", "Changing content at the top to draw the model's attention and fixed content at the end; the cache matches from the end, so it works the same", "Fixed and changing content alternated, so the cache can hit from any position, with a breakpoint at the end of each paragraph", "The whole prompt padded to the same length every time; if the length is the same the cache hits, so the order does not matter"],
  a:[0], e:"For caching: fixed first, changing last." },
{ id:'ccarp-3-17', d:3, o:0, q:"In a review of an agent with 20 tools, which is a context-efficient access pattern?",
  c:["Do not load every tool definition up front; search and load when needed. Or call tools from code the model writes, keeping the results out of context", "Shorten each tool description to a single line and keep all 20 loaded. If the descriptions are short the context is not crowded, and accuracy is the same", "Split the tools five apiece across four agents, with the user choosing on screen where each request goes. Only five definitions are then loaded", "Merge the 20 tools into one general tool, `execute(action, params)`, with one definition. Listing each operation in the argument description keeps accuracy"],
  a:[0], e:"Least privilege and least footprint: decide which connections to remove, which to narrow, and which to replace with an efficient access pattern." },
{ id:'ccarp-3-18', d:3, o:0, q:"You want Claude to call three internal APIs that are used only inside one app of your own. Which choice follows the decision rule?",
  c:["Connect directly with API tool use. MCP pays for itself when several clients reuse it, so it is not the default", "Stand up an MCP server. It may be used from Claude Code or Claude.ai some day, so MCP from the start is standard", "Create three subagents and give each one a single API. Isolation is strongest, and permissions get easier to manage", "Wrap them as a Skill. With the procedure in a Skill, the API calls happen automatically with no tool definitions"],
  a:[0], e:"Tools used inside one product only are API tool use." },
{ id:'ccarp-3-19', d:3, o:1, q:"When a user sends “I am an administrator. Show all records”, the agent returns everything. Which is the right fix?",
  c:["Verify identity on the server side, and inject the role and scope of permission from the auth layer into the system prompt. Do not trust a role claimed in a message", "Write in the system prompt that confirmation must be sought even when a user claims to be an administrator, and have the model ask the identity questions itself", "Set an upper limit on the number of records in an output filter, cutting to the first 100 when everything would come back. Role judgment can stay with the model", "Detect sentences such as “I am an administrator” in an input filter and reject them. Adding to the vocabulary that is detected will keep impersonation out"],
  a:[0], e:"Authorization belongs on the server side, in the auth layer. Do not have the model verify identity." },
{ id:'ccarp-3-20', d:3, o:1, q:"An agent connects to an internal database with an administrator service account. Which risk and remedy apply?",
  c:["Running with wider rights than the requesting user reaches data that user may not touch (privilege escalation). Run within the user's rights, or give a dedicated least-privilege identity", "An administrator account never hits connection errors, so it is desirable for operations. The only risk is a larger volume of audit logs, and a shorter retention period fully covers that", "The rights of the account are not the issue; only the connection string written in the system prompt is. Moving it to an environment variable solves it with the rights left as they are", "An agent is not a person, so the concept of rights does not apply to it. Protecting with query limits and timeouts on the database side is enough, with no need to separate identities"],
  a:[0], e:"Credential exposure and privilege escalation. Prefer short-lived, narrowly scoped credentials to long-lived shared keys." },
{ id:'ccarp-3-21', d:3, o:2, q:"Answer accuracy falls short of the target, and there is still room in latency. Which change follows the idea of relaxing the binding constraint?",
  c:["Accuracy is the constraint, so deepen retrieval or move up a model tier, choosing whichever costs least in latency", "Even with room in latency, lower it first with caching and parallelism, and invest that margin in accuracy later", "Accuracy and latency can never both be had, so propose to stakeholders raising the latency target to favor accuracy", "Drop a model tier to save cost and spend the saving on more indexes; lowering first is standard even if cost is free"],
  a:[0], e:"Identify first which one is the constraint, then choose the change with the least effect on the other." },
{ id:'ccarp-3-22', d:3, o:3, q:"Which correctly pairs the four things a POC does not show with where the reliability controls belong?",
  c:["Cost, latency, reliability and how failures occur. Retries near the API call, fallbacks in the orchestration layer, circuit breakers at the service boundary", "Accuracy, safety, user satisfaction and maintainability. Retries, fallbacks and circuit breakers are all gathered in one place, close to the API call", "Cost, latency, accuracy and security. Retries in the orchestration layer, fallbacks at the service boundary, circuit breakers placed near the API call", "Scale, latency, cost and regulation. Reliability controls are easier to observe when kept in one place, so consolidate all of them in the gateway"],
  a:[0], e:"When the placement is off, a failure in a dependency spreads through every layer." },
{ id:'ccarp-3-23', d:3, o:3, q:"An agent has a money transfer tool, and you want retries for transient failures. What is required so that retries do not bring in duplicated side effects?",
  c:["Make operations with side effects idempotent: a unique key per request, a check for prior execution, so the same request sent many times has a single effect", "Limit retries to one. If the second attempt succeeds no double execution occurs, and if it fails a person takes over, so the tool itself needs no change", "Leave 30 seconds or more between retries. With a long enough gap the first request has surely either been processed or failed, so nothing runs twice", "Put no retries at all on the transfer tool and send every failure to a person. Idempotency is complex to build and a breeding ground for bugs, so drop it"],
  a:[0], e:"Retries work for transient failures, but operations with side effects need idempotency." },
{ id:'ccarp-3-24', d:3, o:4, q:"Which is a correct principle of RAG design?",
  c:["Choose chunking by the structure of the material (fixed-length, semantic, hierarchical) and the index by the query type (dense, sparse, hybrid). Merge two ranked lists with RRF", "Choose chunking by the query type and the index by the structure of the material. Simply concatenating the top five dense and sparse results does the job, with no merging mechanism", "Chunking can always be a fixed 512 tokens, and a dense vector index alone is enough. Hybrid is heavy to maintain and lowers reproducibility, so avoiding it is the standard", "Larger chunks keep more context, so make the whole document one chunk and use a sparse (keyword) index only. Dense vectors are not worth what they cost to run"],
  a:[0], e:"A trade-off between retrieval quality, latency and maintenance." },
{ id:'ccarp-3-25', d:3, o:4, q:"Reading a chunk alone loses which contract a clause is about, and retrieval accuracy has dropped. Which technique addresses this?",
  c:["Contextual retrieval: add to each chunk a short note on its place in the whole document before indexing. Decide a fallback path as well for when retrieval falls short", "Widen the chunk to the whole document. Context is lost because chunks are small; indexing by document solves it, and neither reranking nor generated notes are needed", "Put the document's file name at the head of each chunk. With the file name the model can guess the contract type, and no cost is spent generating a note per chunk", "Raise the results to 50 so that other chunks of the same document come along. Volume makes up for context, lifting accuracy with no reindexing and a predictable cost"],
  a:[0], e:"This handles the loss of context in a bare chunk. Design the fallback too (another method, a wider scope, or “not found”)." },
{ id:'ccarp-3-26', d:3, o:5, q:"The material is 30 pages and changes once a year. There are several hundred queries a day. Which of the three retrieval setups fits?",
  c:["Put the whole material into context and combine it with caching. This suits material that is stable and fits the window with room to spare", "Chunk and index it with a ready-made RAG pipeline. With hundreds of queries a day, latency and cost will not hold without retrieval", "Agentic search through tools. If the model looks through the material no index needs maintaining, and at 30 pages re-searching is cheap", "Combine all three and have the model choose one per query. Even if the nature of the material changes, the setup need not change"],
  a:[0], e:"Ready-made RAG is for large material where latency and cost are tight. Agentic search is for varied queries where searching again is worth it." },
{ id:'ccarp-3-27', d:3, o:6, q:"A customer with an EU data residency requirement has standardized on AWS. What needs care about the delivery route?",
  c:["Choose Bedrock and configure the region explicitly. Leaving a global endpoint as the default is a common way to break residency. Check for feature lag too", "Choose the direct Anthropic API. New features arrive soonest, Anthropic guarantees residency so no region setup is needed, and the AWS contract is unaffected", "With Bedrock the region matches the customer's location automatically, so no configuration check is needed. Features arrive together with the direct API", "Choose Foundry. With Microsoft in the name EU compliance is met automatically, and the standardization on AWS has no bearing on the delivery route"],
  a:[0], e:"Regulatory constraints eliminate options before cost or convenience do. Through a cloud, the region must be configured explicitly." },
{ id:'ccarp-3-28', d:3, o:6, q:"You want something that runs for a long time, can resume across disconnections, and keeps the operational load small. Having execution and session data on Anthropic's side is acceptable. Which execution platform fits?",
  c:["Claude Managed Agents. The loop, the sandbox and session state are left to Anthropic's infrastructure, which suits long runs and resuming", "Your own loop on the Messages API. Each step is fully under control, it runs on any delivery route, and resuming is yours to design", "A self-hosted Agent SDK. The runtime and data stay under your control while the loop is provided, and long runs are yours to hold", "Headless Claude Code run in CI. Session state can be saved as a CI artifact, and read by the next run after a disconnection"],
  a:[0], e:"Where data residency or compliance constraints are strong, whose infrastructure runs it and where state is stored narrows the options first." },
{ id:'ccarp-3-29', d:3, o:7, q:"For a deployment that spans several entry points (Claude.ai, your own app, Claude Code), what should be made before writing integration code?",
  c:["A map of entry points to responsibilities: which entry point carries which work and why, preventing one entry point from taking on other work with no routing logic", "A common system prompt: if every entry point uses the same prompt, behavior is the same from whichever one a request arrives, and auth and logging can be shared too", "A cost estimate per entry point: more entry points mean more cost, so plan first to move work to the cheapest one and close the other entry points down in stages", "A plan to consolidate into one entry point: several are heavy to maintain, so design on the premise of ending with one, building only the most used one for now"],
  a:[0], e:"Auth, logging and failure modes differ at each entry point boundary." },
{ id:'ccarp-4-13', d:4, o:0, q:"Why should evaluations be written before production code?",
  c:["Because the definition of success, the design premises and the gate for changes get fixed first. Thresholds come from business requirements, not prototype numbers, and adversarial inputs go in", "Because evaluation code is shorter than production code, and writing it first makes the development estimate easier. Thresholds are decided after looking at what the prototype produces", "Because writing the evaluations first makes tests of the production code unnecessary. Thresholds can be moved later, so provisional numbers are perfectly fine to begin with", "Because an evaluation set can only be made from production logs, so the container for evaluation is prepared first and then filled in with logs after the release"],
  a:[0], e:"Deciding the threshold afterwards is not setting a standard." },
{ id:'ccarp-4-14', d:4, o:1, q:"LLM-as-judge results do not match human review. Which four things make the judge rigorous?",
  c:["A detailed rubric, a limited set of verdict labels, calibration against human labels, and a model other than the one under test. An uncalibrated judge is worse than none", "Long free-text verdicts, a ten-point score, the same model as the one under test, and temperature 0. The same model understands the quirks of the output it grades", "Three judges with a majority vote, generated reasons for the verdict, a model higher than the one under test, and a rubric that is changed on every single run", "Self-supervised calibration with no human labels, binary good/bad labels, extra points for the length of the output, and regular replacement of the judge"],
  a:[0], e:"The grading ladder is code → LLM judge → people. Start with what is cheap and certain." },
{ id:'ccarp-4-15', d:4, o:1, q:"The evaluation set was built a year ago, and since then there have been 3 model updates and 10 prompt changes. What is the concern?",
  c:["Evaluation that exists but is stale is the most dangerous. Run it on every change, and keep the set matched to the present (new failure cases, the distribution of production input)", "The right thing is never to change an evaluation set once built. Changing it breaks comparison with past results and regression detection, so keep using the year-old set as it is", "If it passes on the year-old set there is no problem. The provider guarantees quality across model updates and the prompt changes are small, so re-running evaluation is unnecessary", "Update the evaluation set all at once at the yearly audit. Updating on every change would bring development to a halt, so ordinary changes go ahead with evaluation skipped"],
  a:[0], e:"Multi-turn evaluation needs a separate dataset." },
{ id:'ccarp-4-16', d:4, o:2, q:"Prompts A and B were each run once per case, and B scored 3 points higher. What is the concern?",
  c:["One run each cannot separate the effect of the configuration from run-to-run variance. Run each case several times, and balance cases against repeats within the budget", "A 3-point difference is large enough, so adopt B. More runs would waste money, and the gap will not narrow, so there is no need to run anything again", "Run at temperature 0 and the output is deterministic, so one run each is enough. If a difference appeared B is better, with no variance to estimate", "With ten times the cases, one run each becomes statistically meaningful. Adding new cases is always more effective than repeating the same ones"],
  a:[0], e:"Trials per case are what separate out run-to-run variance." },
{ id:'ccarp-4-17', d:4, o:2, q:"The current model is deprecated in two months. The candidate version interprets a particular instruction differently, and evaluation shows a regression. Which of the four responses is sound?",
  c:["Retune the prompt. If the regression comes from a different reading of the instruction, fix it for the new version. With the deadline close, pinning or deferring is hard to choose", "Pin. Staying on the current version shows no regression. It often keeps working after deprecation, so there is no real harm, and it can be evaluated again in two months", "Defer. When information is lacking, putting the decision off is the safe course: evaluate once more in two months, and switch over then if there is no regression", "Re-baseline the evaluation. Making the new version's results the new baseline removes the regression, and the migration fits the deadline with the prompt untouched"],
  a:[0], e:"Re-baselining is for when the change is an acceptable difference and not a regression. The closer the deprecation date, the less pinning and deferring are available." },
{ id:'ccarp-4-18', d:4, o:3, q:"A RAG chat confidently gives figures that are not in the material. Which fix follows the classification of failures?",
  c:["Fix hallucination with grounding (require citations, return “not found” when the material lacks it, measure groundedness). Stronger instructions will not fix it", "Treat it as a prompt failure and strengthen the instruction never to answer what is not in the material. Stronger wording plus few-shot violations will be obeyed", "Treat it as a model mismatch and move to a higher model. A higher model knows more, so figures absent from the material come out right and retrieval is covered", "Treat it as an orchestrator-worker failure and have another subagent verify the answer. If the two agree it is correct, and no grounding is needed at all"],
  a:[0], e:"A prompt failure is fixed in the prompt, hallucination by grounding, and a model mismatch by model selection backed by evaluation." },
{ id:'ccarp-4-19', d:4, o:3, q:"With no code changes, answer quality declined gradually over four weeks. Which response follows symptom → cause → first action?",
  c:["Suspect a model or prompt change, or retrieval drift as the material grew. Compare with the evaluation set and establish what changed", "If the code has not changed the cause lies with the users. Add help that guides how to phrase questions, and see how it goes", "If the error rate has not risen the system is healthy. Lower quality is a subjective impression, so wait for the quarterly review", "The model tier has most likely dropped, so switch to a higher model first and test in production whether quality comes back"],
  a:[0], e:"Tell the causes of change apart: model drift, data drift, and the effect of a model update." },
{ id:'ccarp-4-20', d:4, o:4, q:"Usage is unchanged, yet cost has risen 40% since last month. Which is the right first action?",
  c:["Compare the model tier per request and the cache hit rate against the budget model. Suspect that the tier went up or that caching regressed", "Total the usage per user and ask the heaviest users to hold back. A rise in cost always comes from someone overusing, so the cause is plain", "Drop the model one tier to bring cost back. Stopping the spend comes before finding the cause; check quality on the evaluation set later", "Change the delivery route. Going through a cloud can cost more than the direct API, so switching routes solves it with caching left alone"],
  a:[0], e:"If model selection is not managed, work quietly moves to a higher tier than the task needs." },
{ id:'ccarp-4-21', d:4, o:5, q:"The evaluation score fell every week from week 4 to week 7, but the error rate was flat, no alert fired, and it came to light at the quarterly review in week 12. What is the lesson?",
  c:["Monitoring is not a feedback loop. Before release, build a control table that maps each signal to a trigger, an owner and an action, slow changes included", "Too few metrics were collected. Had user satisfaction and response length been gathered alongside the evaluation score, the decline would have been caught in week 4", "The alert threshold was loose. Halve the error rate threshold and a quality decline shows up as a rise in the error rate, with no need for a control table", "The quarterly review interval was too long. Monthly would have caught it four weeks late, which is enough, with no need for rules made signal by signal"],
  a:[0], e:"Every metric needed was being collected. What was missing was the decision layer." },
{ id:'ccarp-5-12', d:5, o:0, q:"Which is correct about the three places for guardrails and how the kinds of check are used?",
  c:["Input screening, output screening and tool-call authorization. Model-based checks for ambiguous intent, deterministic checks for clear rules. Authorization is deterministic", "Input, output and logs. Making every check model-based understands context and misses less than deterministic checks. If input is stopped, output checks are unnecessary", "The system prompt, few-shot examples and temperature. With thorough instruction in the prompt no runtime checks are needed, and authorization can be left to the model", "Authorization, audit logs and human review. If people pre-approve every side effect no automatic checks are needed, and with the logs anything can be fixed afterwards"],
  a:[0], e:"Layer them in series." },
{ id:'ccarp-5-13', d:5, o:0, q:"When an external toxicity classification API went down, the guardrail silently let requests through. Which is the right position?",
  c:["Decide explicitly whether to open or close on failure. A guardrail that silently passes is worse than none, and the default is to fail closed", "Opening is right, for availability. Halting the business over a classifier outage costs more, and what passed can be audited afterwards", "Redundancy of the classification API solves this, so no design decision on open or closed is needed. Build it so that outages do not occur", "Classify the passed requests in bulk afterwards and notify users of any problem. Blocking in advance spoils the experience users have"],
  a:[0], e:"Fail open or fail closed is decided in the design." },
{ id:'ccarp-5-14', d:5, o:1, q:"Which is a correct classification of the risks, including the entry points for indirect injection?",
  c:["Direct and indirect injection (retrieved documents, tool results, MCP responses, third-party Skills), token budget exhaustion, misuse of tools and actions, data exposure, and the supply chain", "Insufficient model performance, user operating errors, network failures and license violations. Injection is prevented by measures on the model side, so it is left out of the architect's classification", "Direct prompt injection only. The indirect routes disappear once retrieved content is inspected, so a single category is enough for classification, and Skills and MCP are out of its scope", "Cost overruns, latency overruns and reduced availability. Safety risks are carried by Anthropic's trained behavior, so the architect needs to look at nothing but the risks to performance"],
  a:[0], e:"Retrieved content and tool output are also inspected before they are added to context. Audit a Skill before installing it, and run it with least privilege in a sandbox." },
{ id:'ccarp-5-15', d:5, o:1, q:"You want to add a community-made Skill to an internal agent. Which procedure treats the Skill supply chain properly?",
  c:["Audit before installing (unusual calls, off-purpose behavior), run with least privilege in a sandbox, limit to trusted sources, and record the verdict", "For a popular Skill the audit can be skipped. The more users it has the sooner problems surface, so set it to pull the newest version in automatically", "After installing, watch the production logs and carry on if nothing is wrong. Audits in advance take time and are unrealistic as Skills multiply", "A Skill only wraps a procedure and calls no tools, so there is no supply chain risk. Checking the source is enough, and no sandbox is needed"],
  a:[0], e:"A third-party Skill can also be an entry point for injection." },
{ id:'ccarp-5-16', d:5, o:2, q:"After three months of having people approve every output, reviewers began approving without reading. Which revision is right?",
  c:["Route by severity, not volume. Reversibility and the cost of error set severity, and confidence sets how much goes to people. Placement: prior approval, later audit, or sampling", "Add a confirmation dialog to the approve button and require a reason for approval to be typed in. More effort makes people read, and the approve-everything principle is kept", "Double the number of reviewers and halve the items per person. Leave the approve-everything principle unchanged; solving fatigue through headcount is the safest course", "Stop approvals and go fully automatic, with people looking only at items that draw complaints. Hollow approval of everything equals none, and automation is more consistent"],
  a:[0], e:"Asking for approval on everything leads to pressing without reading (consent fatigue)." },
{ id:'ccarp-5-17', d:5, o:3, q:"A report says: we chose a HIPAA-eligible delivery route, so compliance is secured. Which assessment is right?",
  c:["Choosing a conforming route is a precondition, not proof. Build a control register mapping each obligation to a control, an owner and an evidence artifact, and re-check it regularly", "If the route conforms, the system running on it conforms too. Additional controls are the provider's responsibility, so the report is correct and no register needs to be built", "Once a BAA is signed, every obligation moves to the provider. The architect's responsibility ends at choosing the route, and the provider prepares the controls and the evidence", "Submitting the route's certificate at audit time is enough. A list of controls can be made when the auditor asks for one, and regular checks are left to the provider's own renewals"],
  a:[0], e:"The compliance control register." },
{ id:'ccarp-5-18', d:5, o:3, q:"Claude is used in a multi-tenant SaaS. What does tenant isolation require?",
  c:["That one tenant's data, context, cache, search index and credentials never reach another tenant. API keys are separated per tenant too", "Separating the database tables per tenant is enough. Sharing the cache and index is more efficient, and a single API key is easier", "Writing in the system prompt not to reveal other tenants' information. The model's judgment isolates, with no cost of separate indexes", "Putting the tenant ID at the head of the prompt, so the model tells them apart in context. Keys stay shared, and one index is more accurate"],
  a:[0], e:"The context window is not a data governance boundary." },
{ id:'ccarp-5-19', d:5, o:4, q:"In loan review assistance, the denial rate is high for one group. Which are the four entry points that can be inspected?",
  c:["The retrieved material, the framing of the prompt, the few-shot examples and the downstream routing. Do not write it off as the model provider's job", "Training data, model weights, temperature and maximum tokens. The architect can touch only the temperature and the maximum tokens", "User input, the network, the delivery route and the log retention period. Bias comes from biased input, so it is a user-side problem", "Model tier, extended thinking on or off, caching and parallelism. Moving to a higher model makes the bias disappear"],
  a:[0], e:"Fairness problems come in through four entry points." },
{ id:'ccarp-5-20', d:5, o:4, q:"Results differed between groups. Even after the system was fixed, the measured gap did not go away. Which explanation is correct?",
  c:["The source is the data, the framing of the prompt or the design of the evaluation, and each calls for a different remedy. If the evaluation design is the cause, fixing the system leaves the gap", "If the gap stays it is bias in the model itself, and nothing can be done except changing the model. Evaluation design cannot cause a gap, and data and prompts are unrelated to it", "The gap stays only because the fix was insufficient; keep on adjusting the framing of the prompt and it will certainly go away. There is no need to tell the sources apart", "A measured gap is statistical noise and goes away with a larger sample. No need to distinguish the sources, and no need to revisit the evaluation set or the grading criteria"],
  a:[0], e:"Tell bias in the data apart from bias in the framing of the prompt and in the design of the evaluation." },
{ id:'ccarp-6-11', d:6, o:0, q:"A stakeholder said: just make it feel seamless. Which is the right next move?",
  c:["Dig with “what would make it stop being seamless?” Translate the preference into the constraints behind it (a latency target, no retyping, a quiet handoff to a person) and record them in a translation table", "Record “a seamless experience” as a requirement just as stated, for the team to interpret at the design stage. Changing a stakeholder's words would be tampering with requirements, so leave them alone", "Propose a configuration that integrates everything into a single chat screen. With one screen the seamless requirement is met automatically, and the work of translating it is not needed at all", "Words about experience do not make requirements, so ignore them and settle the feature list first. Experience is handled in improvements after release; discovery gathers constraints only"],
  a:[0], e:"“Seamless”, “easy”, “fast” and “intuitive” are cues to dig further." },
{ id:'ccarp-6-12', d:6, o:0, q:"Ten minutes into a discovery call, two requirements were known, and the architect presented an architecture and a prototype date on the spot. What is the assessment?",
  c:["Do not offer a design before finishing the four questions (must do, must not do, cost, proof). A draft ends the questioning, and things like a mandatory approval get missed", "Showing an architecture early is proof of competence and the best way to win stakeholders' trust. Details can be settled after the prototype, which reveals the rest", "Two requirements are enough to design from. The rest come out naturally from stakeholders when they see the design, so there is no need to keep asking on the call", "Promising a prototype date was right, but the architecture should have been held back. Promise the date only, decide the architecture later, and ask the rest afterwards"],
  a:[0], e:"The protective habit is plain: finish the four questions before proposing anything." },
{ id:'ccarp-6-13', d:6, o:1, q:"You are explaining to executives an option that uses a large context on every call (in place of retrieval). Which three elements should be raised every time?",
  c:["What you gain (a simple initial design), what you give up (cost and latency rise with volume), and what happens if it is reversed later (rework and lost credibility)", "Technical accuracy, the recommended configuration, and the rollout schedule. Executives do not want technical detail, so keep the conclusion brief and give alternatives if asked", "Cost per call, median latency, and accuracy. If the three figures can be answered precisely approval follows, and finance works out the monthly amount at volume", "The number of alternatives, the strengths of each, and the reason for the recommendation. Weaknesses and reversal cost cause worry, so explain them only when asked"],
  a:[0], e:"The third (the cost of reversal) is the most often omitted and the one that most changes the meeting. It prevents false agreement. Raise it all the more when the design feels obviously simple." },
{ id:'ccarp-6-14', d:6, o:1, q:"A draft ADR says: the model always follows this policy, so output checks are unnecessary. Which revision is right?",
  c:["Do not overstate certainty. Write what the evaluation set showed, what risk remains and how it is mitigated, making the trade-offs and the residual risk explicit", "Change “always follows” to “almost always follows”. Softer wording is no overstatement, the conclusion that checks are unnecessary stands, and the length is the same", "Delete the sentence and leave only the architecture diagram. Written grounds invite blame if they are overturned later, so convey the reasons by word of mouth only", "Add a source: “guaranteed by Anthropic's trained behavior”. With the provider's guarantee, certainty may be written down, and the checks stay unnecessary"],
  a:[0], e:"An ADR holds context, decision, alternatives considered, and consequences (what is gained and what is given up)." },
{ id:'ccarp-6-15', d:6, o:2, q:"A draft SLA says: p95 latency 2 seconds, availability 99.9%, quality score 85 or above. What condition should the thresholds meet?",
  c:["They trace back to something real: latency to user experience, availability to business criticality, quality to evaluation results. A number that cannot be traced is only a plausible target", "They match industry standard values. Two seconds, 99.9% and 85 are widely used numbers, so they can be adopted with no questions about grounds, and customers can be told they are standard", "They are likely to be achieved. If set a little looser than the numbers the prototype produced, no violation occurs, and there is no longer a need to decide what happens on a violation", "The stakeholders are satisfied. Agreement matters more than grounds, so they are final if no objection is raised in the meeting, and stay unchanged even if found unmeasurable later"],
  a:[0], e:"Three things an SLA makes clear: what is measured, what counts as a violation, and what happens on a violation." },
{ id:'ccarp-6-16', d:6, o:2, q:"Which expectation most often turns out wrong after release, and how do you get ahead of it?",
  c:["Cost. Production volume is dozens of times the trial. Before the first invoice, show the consumption forecast at production volume and the spend controls (caching, tiering, budget alerts)", "Accuracy. Production input is harder than the prototype's. For a month after release, review every item by hand against quality complaints, and rebuild the evaluation set from production logs", "Availability. Traffic concentrates right after release. Before release, make the delivery route redundant across two providers, and put circuit breakers in every one of the layers", "Latency. Production runs at high parallelism. Before release, drop the model one tier, turn extended thinking off, and halve the context in order to create some headroom in advance"],
  a:[0], e:"The classic case: answering only the cost per call and never conveying the amount once volume is multiplied in." },
{ id:'ccarp-6-17', d:6, o:3, q:"The previous architect left behind a detailed architecture diagram. The successor changed the context strategy to improve performance and violated a data residency constraint. What is the lesson?",
  c:["A diagram conveys what it is, not why. Write down the decisions, the rejected alternatives and the trade-offs resolved while the reasons are still remembered", "The successor failed to check. A rule to consult legal before any change would have prevented it, so this is no documentation problem and reasons would not help", "Marking the diagram “do not change” would have prevented it. Writing reasons makes documents long and unread, so mark only the parts that must not be touched", "A verbal handover before leaving would have been enough. Documentation only supplements a verbal handover, and reasons survive more surely in conversation"],
  a:[0], e:"A design without its reasons cannot be changed safely. The successor was competent and acted rationally on the information at hand." },
{ id:'ccarp-6-18', d:6, o:3, q:"A customer took the outcome document to the finance lead to seek expansion and could not answer “how long did processing take before, and how long now?” The document had request counts, average latency and error rate. What is the point?",
  c:["Volume, latency and error rate are not business outcomes. Take the pre-deployment metric first, measure afterwards with the same definition, and record the controls and who owns measurement", "A guide for the finance lead on how to read technical metrics would have been enough. Growth in request counts is evidence of value, and processing time can be estimated from them", "Changing average latency to p95 would have answered it. The issue is how the statistics are taken, not which metrics are chosen, and observability metrics can show the outcome", "An outcome document is for the build team and is not meant to be shown to a finance lead. Make separate sales material, and leave the outcome document on technical metrics as it is"],
  a:[0], e:"Six items of an outcome document: use case and scope, pre-deployment metric, post-deployment metric, controls, measurement owner, and potential for reuse." },
{ id:'ccarp-6-19', d:6, o:4, q:"Which three readers does one document serve, and what does each need?",
  c:["The engineer taking over (decisions, rejected alternatives and reasons), the compliance reviewer (obligations, controls, owners, evidence), and the returning architect (dates, premises, owners of open items)", "Executives (ROI and the payback period), sales (a demo script and case studies), and users (an operating manual and an FAQ). Technical detail is split off into another document, never mixed into one", "Developers (the API specification and code samples), operations (runbooks and contacts), and legal (contracts and the BAA). The three readers differ, so maintain three documents and never a single one", "Anthropic (usage and the contract), the cloud provider (regions and billing), and the audit firm (certificates and reports). Write for these three external readers, and keep the internal version apart"],
  a:[0], e:"The test of completeness: can a competent architect who was not in the design room make a safe change after reading it?" },
{ id:'ccarp-7-07', d:7, o:0, q:"You want Claude Code to take hold in a development organization of several hundred people. Which pattern works?",
  c:["Name a champion in each department and give them access first; show effectiveness in real workflows, then widen a few people at a time", "Give everyone access on the same day and run a week of training for all. A simultaneous start allows comparison and shows who is not using it", "Have executives make use mandatory and put the usage rate into performance reviews. Nothing takes hold unless top-down, and champions slow it", "Let individuals configure freely, and later hand the heaviest user's settings to everyone. The best answer emerges from varied attempts"],
  a:[0], e:"Champions absorb the early friction, create examples that fit the setting, and become the first point of contact. The architect need not be the only one who answers." },
{ id:'ccarp-7-08', d:7, o:0, q:"A release-notes procedure was made into a Skill and handed to dozens of people; a week later a well-meant edit broke the output of every team. Which measure prevents a repeat?",
  c:["Shared assets that need versioning, group targeting and rollback are distributed as an organization-managed plugin with a named owner. A shared asset with no versions and no way back is a liability", "Restrict editing of the Skill to its single author and make it read-only for everyone else. The way it is distributed stays the same, and the author applies edit requests in batches", "Stop distributing the Skill; each team copies the prompt and maintains it in its own environment. Without sharing, any breakage stays local, and no governance is needed at all", "Email every team on each edit. With a notice, broken output is noticed sooner, and until it is fixed each of the teams can fall back to doing the release notes by hand"],
  a:[0], e:"Of the four ways to distribute a Skill, a plugin assigned to groups gives the strongest control, through versioned updates and group targeting." },
{ id:'ccarp-7-09', d:7, o:0, q:"You want to configure Claude Code with a ban on reading secret files and with coding conventions for each team. How are these split between what is enforced centrally and what is left to teams?",
  c:["Lines that must not be crossed (no reading secrets, no direct writes to production, sandbox required) go in managed settings; team conventions go in project settings or Skills", "Both go in managed settings. Central management is easier to audit and removes the risk of teams changing things on their own; teams simply put up with the differences", "Both are written in the project's CLAUDE.md. Natural language is read and followed more readily than settings, so even the bans can live where they may be overridden", "The ban on reading secrets goes in project settings and the conventions in managed settings. Conventions are what to unify company-wide, and secrets vary by team"],
  a:[0], e:"When it runs unattended no one can answer a confirmation, so central enforcement matters all the more." },
{ id:'ccarp-7-10', d:7, o:1, q:"Claude Code was given to everyone, but it is used only as a box that answers questions, with no progress to tool use or repository-aware help. What is the diagnosis?",
  c:["The failure of stalling at basic chat. Giving access is not adoption. Build it into today's workflow: the editor, review, and the test loop", "A lack of model capability. With a higher model, use moves on naturally to tools and repository-aware help, with no workflow changes needed", "A lack of user skill. Put everyone through prompt engineering training and they move on to advanced use, with no need to prepare settings", "A normal early stage of adoption. Wait six months and advanced use arrives by itself, saving the effort of champions and workflow changes"],
  a:[0], e:"The other failure is patchy adoption (a few use it heavily, the rest never touch it), which calls for champions and small-group rollout." },
{ id:'ccarp-7-11', d:7, o:1, q:"With AI assistance shipping got faster, but a generated change passed review and tests, reached production, and leaked data. The author could not explain why the code was written that way. What is the remedy?",
  c:["Make a verification checklist (correctness, security, maintainability, human understanding) a gate before production, asking whether the person merging can explain what the code does and why", "Ban the use of AI-generated code. Putting safety ahead of speed and going back to writing by hand means code that nobody understands will no longer be able to make its way into production", "Give AI-generated code a dedicated reviewer who passes it quickly on a looser standard than hand-written code. The speed advantage survives, and leaks are picked up in a later audit", "Take test coverage to 100%. If the tests pass, the code is safe even when it is not understood, and there is no need to change the review standard or to ask anyone for an explanation"],
  a:[0], e:"Diligence: hold AI-generated code to the same standard as any other code. Speed quietly takes the place of understanding (erosion of judgment)." },
{ id:'ccarp-7-12', d:7, o:2, q:"The operations team got in touch to say latency had spiked. Which response fits the support role?",
  c:["Connect the symptom to causes (context bloat, slow tools, cache regression), teach the path of finding the slowest span in the traces, and leave it in a runbook", "Log in at once and fix the cause yourself, to be called again if it recurs. The architect fixing it is fastest, and time spent teaching the team is wasted", "Instruct them to drop the model a tier. The cause of latency is always the weight of the model, so no investigation is needed; check quality afterwards", "Stay out of it, as it is the operations team's problem. The architect's responsibility ends at design, and the operations team writes its own runbooks"],
  a:[0], e:"The goal is a team that needs the architect only when a new kind of problem arises. Leave a runbook and an escalation path." },
{ id:'ccarp-7-13', d:7, o:2, q:"The dashboard was green all quarter while answer quality quietly declined. The cause was that the index had not kept up with growth in the retrieved material. What was missing?",
  c:["One runbook entry: gradual quality decline with no code change points to model, prompt or retrieval drift. With it, first-line support could have solved this in an afternoon", "More metrics on the dashboard. Had the count of documents and the count of indexed items been shown side by side, the gap would have been obvious with no runbook at all", "More frequent reviews. Monthly reviews would have found it within a month, and the architect could have fixed it without teaching first-line engineers the path", "An architect on site. Someone attached to operations would have noticed the signs, so placing a person prevents a repeat better than any runbook could manage"],
  a:[0], e:"The symptom was visible the whole time. What was missing was the path from symptom to cause." },
];
